-- Historical recorded migration; disposable PostgreSQL QA only.
create table if not exists public.marketplace_handover_events (
  id bigint generated by default as identity primary key,
  order_id text not null,
  job_id text,
  event text not null check (event in ('vendor_handover_confirmed','customer_delivery_confirmed')),
  actor_type text not null check (actor_type in ('vendor','member')),
  actor_id text not null,
  created_at timestamptz not null default now(),
  metadata jsonb not null default '{}'::jsonb
);
create unique index if not exists marketplace_handover_events_order_event_uidx on public.marketplace_handover_events(order_id,event);
create index if not exists marketplace_handover_events_job_idx on public.marketplace_handover_events(job_id);
revoke all on table public.marketplace_handover_events from anon, authenticated;

